compact/powershell/claude-code/ollama-em.copy:
# Keep generated configuration files out of version control.
if (-not (Test-Path .gitignore)) { New-Item -ItemType File -Path .gitignore | Out-Null }
Add-Content -Path .gitignore -Value '.chunkhound.json'
# Configure ChunkHound with Ollama embeddings and OrcaRouter for research. Embedding and LLM providers are independent — either works without the other. Field details: https://chunkhound.ai/docs/configuration/
# You'll need: OrcaRouter API key
@'
{
  "embedding": {
    "provider": "openai",
    "model": "qwen3-embedding",
    "base_url": "http://localhost:11434/v1"
  },
  "llm": {
    "provider": "orcarouter",
    "model": "qwen/qwen3.7-flash",
    "api_key": "<YOUR_ORCAROUTER_API_KEY>"
  }
}
'@ | Set-Content -Path '.chunkhound.json' -Encoding utf8
# Configure Claude Code to connect to ChunkHound via MCP.
claude mcp add ChunkHound -- chunkhound mcp
# Build ChunkHound's search index for this project.
chunkhound index .

